parameters.query:


select * from  contab.vw_contas_validas_compra_cartao  

WHERE empresa_id = {{ $json.empresa_id }}

ORDER BY codigo;

parameters.jsCode:
 function resolverPai(codigo) {
  if (!codigo) return null;

  const partes = codigo.split(".");
  if (partes.length <= 1) return null;

  partes.pop(); // remove o último nível
  return partes.join(".");
}

// EXEMPLO DE USO
const codigo = $json.codigo; // ex: "5.2.1.2"
const codigoPai = resolverPai(codigo);

return [
  {
    json: {
      ...$json,
      codigo_pai: codigoPai
    }
  }
];

